-- Private immutable dated IVV membership snapshots. No index-effective dates are inferred.
-- Invoker-only service role RPCs; browser roles receive no privileges.
create schema if not exists edgar_private;
revoke all on schema edgar_private from public,anon,authenticated;
grant usage on schema edgar_private to service_role;

create table edgar_private.membership_snapshots (
  namespace text not null check(namespace='production'),
  id text not null check(length(id)<=100),
  source_as_of date not null,
  fingerprint text not null check(fingerprint ~ '^[a-f0-9]{64}$'),
  snapshot jsonb not null check(jsonb_typeof(snapshot)='object' and octet_length(snapshot::text)<=180000),
  evidence_kind text not null check(evidence_kind in ('reviewed-repository-seed','gzip-csv')),
  raw_sha256 text not null check(raw_sha256 ~ '^[a-f0-9]{64}$'),
  raw_bytes integer check(raw_bytes between 1 and 750000),
  gzip_sha256 text check(gzip_sha256 ~ '^[a-f0-9]{64}$'),
  gzip_bytes bytea check(octet_length(gzip_bytes) between 1 and 200000),
  created_at timestamptz not null default clock_timestamp(),
  primary key(namespace,id),
  check((evidence_kind='reviewed-repository-seed' and raw_bytes is null and gzip_bytes is null and gzip_sha256 is null)
    or (evidence_kind='gzip-csv' and raw_bytes is not null and gzip_bytes is not null and gzip_sha256 is not null))
);
create table edgar_private.membership_control (
  namespace text primary key check(namespace='production'),
  active_id text not null,
  candidate_id text,
  next_check_at timestamptz not null default clock_timestamp(),
  last_checked_at timestamptz,
  last_error text check(last_error ~ '^[A-Za-z0-9_]{1,100}$'),
  error_count integer not null default 0 check(error_count between 0 and 3),
  preparation_cursor integer not null default 0 check(preparation_cursor between 0 and 526),
  owner uuid, generation bigint not null default 0,
  lease_until timestamptz,
  foreign key(namespace,active_id) references edgar_private.membership_snapshots(namespace,id),
  foreign key(namespace,candidate_id) references edgar_private.membership_snapshots(namespace,id)
);
create index membership_control_candidate on edgar_private.membership_control(namespace,candidate_id) where candidate_id is not null;
create table edgar_private.membership_activations (
  namespace text not null,
  snapshot_id text not null,
  activated_at timestamptz not null default clock_timestamp(),
  primary key(namespace,snapshot_id),
  foreign key(namespace,snapshot_id) references edgar_private.membership_snapshots(namespace,id)
);
create table edgar_private.membership_retained (
  namespace text not null check(namespace='production'),
  cik text not null check(cik ~ '^[0-9]{10}$' and cik<>'0000000000'),
  issuer jsonb not null check(jsonb_typeof(issuer)='object' and octet_length(issuer::text)<=1200),
  departed_snapshot text not null,
  retained_at timestamptz not null default clock_timestamp(),
  primary key(namespace,cik),
  foreign key(namespace,departed_snapshot) references edgar_private.membership_snapshots(namespace,id)
);
create index membership_retained_snapshot on edgar_private.membership_retained(namespace,departed_snapshot);
create table edgar_private.membership_aliases (
  namespace text not null check(namespace='production'),
  ticker text not null check(ticker ~ '^[A-Z][A-Z0-9-]{0,9}$'),
  cik text not null check(cik ~ '^[0-9]{10}$' and cik<>'0000000000'),
  first_snapshot text not null,
  primary key(namespace,ticker),
  foreign key(namespace,first_snapshot) references edgar_private.membership_snapshots(namespace,id)
);
create index membership_aliases_snapshot on edgar_private.membership_aliases(namespace,first_snapshot);
create table edgar_private.coverage_cycles (
  namespace text not null check(namespace='production'),
  cycle date not null,
  membership_id text not null,
  universe_version text not null check(universe_version ~ '^[a-f0-9]{16}$'),
  companies jsonb not null check(jsonb_typeof(companies)='array' and jsonb_array_length(companies) between 475 and 526 and octet_length(companies::text)<=40000),
  created_at timestamptz not null default clock_timestamp(),
  primary key(namespace,cycle),
  foreign key(namespace,membership_id) references edgar_private.membership_snapshots(namespace,id)
);
create index coverage_cycles_membership on edgar_private.coverage_cycles(namespace,membership_id);

do $$ declare relation text; begin
  foreach relation in array array['membership_snapshots','membership_control','membership_activations','membership_retained','membership_aliases','coverage_cycles'] loop
    execute format('alter table edgar_private.%I enable row level security',relation);
    execute format('revoke all on edgar_private.%I from public,anon,authenticated',relation);
    execute format('grant select,insert on edgar_private.%I to service_role',relation);
  end loop;
end $$;
-- Snapshots, activation history and daily cohorts have no UPDATE or DELETE grant.
grant update on edgar_private.membership_control,edgar_private.membership_retained to service_role;

