"cik":"0001466258"},{"ticker":"TTD","cik":"0001671933"},{"ticker":"TTWO","cik":"0000946581"},{"ticker":"TXN","cik":"0000097476"},{"ticker":"TXT","cik":"0000217346"},{"ticker":"TYL","cik":"0000860731"},{"ticker":"UAL","cik":"0000100517"},{"ticker":"UBER","cik":"0001543151"},{"ticker":"UDR","cik":"0000074208"},{"ticker":"UHS","cik":"0000352915"},{"ticker":"ULTA","cik":"0001403568"},{"ticker":"UNH","cik":"0000731766"},{"ticker":"UNP","cik":"0000100885"},{"ticker":"UPS","cik":"0001090727"},{"ticker":"URI","cik":"0001067701"},{"ticker":"USB","cik":"0000036104"},{"ticker":"V","cik":"0001403161"},{"ticker":"VEEV","cik":"0001393052"},{"ticker":"VICI","cik":"0001705696"},{"ticker":"VLO","cik":"0001035002"},{"ticker":"VLTO","cik":"0001967680"},{"ticker":"VMC","cik":"0001396009"},{"ticker":"VMRK","cik":"0000906107"},{"ticker":"VRSK","cik":"0001442145"},{"ticker":"VRSN","cik":"0001014473"},{"ticker":"VRT","cik":"0001674101"},{"ticker":"VRTX","cik":"0000875320"},{"ticker":"VST","cik":"0001692819"},{"ticker":"VTR","cik":"0000740260"},{"ticker":"VTRS","cik":"0001792044"},{"ticker":"VZ","cik":"0000732712"},{"ticker":"WAB","cik":"0000943452"},{"ticker":"WAT","cik":"0001000697"},{"ticker":"WBD","cik":"0001437107"},{"ticker":"WDAY","cik":"0001327811"},{"ticker":"WDC","cik":"0000106040"},{"ticker":"WEC","cik":"0000783325"},{"ticker":"WELL","cik":"0000766704"},{"ticker":"WFC","cik":"0000072971"},{"ticker":"WM","cik":"0000823768"},{"ticker":"WMB","cik":"0000107263"},{"ticker":"WMT","cik":"0000104169"},{"ticker":"WRB","cik":"0000011544"},{"ticker":"WSM","cik":"0000719955"},{"ticker":"WST","cik":"0000105770"},{"ticker":"WTW","cik":"0001140536"},{"ticker":"WY","cik":"0000106535"},{"ticker":"WYNN","cik":"0001174922"},{"ticker":"XEL","cik":"0000072903"},{"ticker":"XOM","cik":"0002115436"},{"ticker":"XYL","cik":"0001524472"},{"ticker":"XYZ","cik":"0001512673"},{"ticker":"YUM","cik":"0001041061"},{"ticker":"ZBH","cik":"0001136869"},{"ticker":"ZBRA","cik":"0000877212"},{"ticker":"ZTS","cik":"0001555280"}]}$seed$::jsonb)) as seed(s);
insert into edgar_private.membership_control(namespace,active_id)
select namespace,id from edgar_private.membership_snapshots;
insert into edgar_private.membership_activations(namespace,snapshot_id)
select namespace,id from edgar_private.membership_snapshots;

insert into edgar_private.membership_aliases(namespace,ticker,cik,first_snapshot)
select s.namespace,a,i->>'cik',s.id from edgar_private.membership_snapshots s,
  jsonb_array_elements(s.snapshot->'issuers') i,jsonb_array_elements_text(i->'aliases') a;

-- Preserve the rollout day's existing fixed-cohort jobs instead of enqueuing a
-- duplicate full refresh when the dynamic worker first runs. New dates use schema 2.
insert into edgar_private.coverage_cycles(namespace,cycle,membership_id,universe_version,companies)
select s.namespace,(clock_timestamp() at time zone 'UTC')::date,s.id,'8907093474889e5e',
  (select jsonb_agg(jsonb_build_object('cik',cik,'ticker',ticker) order by cik) from (
    select i->>'cik' cik,i->>'ticker' ticker from jsonb_array_elements(s.snapshot->'issuers') i
    union all select '0000002098','ACU') cohort)
from edgar_private.membership_snapshots s
where (select count(*) from public.edgar_ingestion_jobs j where j.namespace=s.namespace and j.dataset='sec'
  and j.job_key ~ ('^sec-coverage-v1:'||to_char(clock_timestamp() at time zone 'UTC','YYYY-MM-DD')||':[0-9]{2}:8907093474889e5e$')
  and j.checkpoint->>'schema'='1' and j.checkpoint->>'universeVersion'='8907093474889e5e')=32;

-- Equivalent to JSON.stringify(sorted issuer tuples), without JSONB display spaces.
create function edgar_private.membership_fingerprint(p_issuers jsonb)
returns text language sql immutable security invoker set search_path='' as $$
  select encode(extensions.digest('['||string_agg(
    '['||to_json(r->>'cik')::text||','||to_json(r->>'ticker')::text||','||to_json(r->>'name')::text||','||
    to_json(r->>'sector')::text||','||to_json(r->>'fund')::text||',['||
    (select string_agg(to_json(a)::text,',' order by a collate "C") from jsonb_array_elements_text(r->'aliases') a)||']]',
    ',' order by r->>'cik')||']','sha256'),'hex') from jsonb_array_elements(p_issuers) r
$$;

create function public.edgar_coverage_registry(p_namespace text)
returns jsonb language plpgsql stable security invoker set search_path='' as $$
declare result jsonb;
begin
  if p_namespace is distinct from 'production' then raise exception 'invalid_membership_namespace' using errcode='22023'; end if;
  select jsonb_build_object('schema',1,'active',a.snapshot,'candidate',b.snapshot,
    'retained',(select coalesce(jsonb_agg(r.issuer order by r.cik),'[]'::jsonb) from edgar_private.membership_retained r
      where r.namespace=p_namespace and not exists(select 1 from jsonb_array_elements(a.snapshot->'issuers') i where i->>'cik'=r.cik)),
    'control',jsonb_build_object('nextCheckAt',c.next_check_at,'lastCheckedAt',c.last_checked_at,
      'lastError',c.last_error,'errorCount',c.error_count,'preparationCursor',c.preparation_cursor,'leaseUntil',c.lease_until)) into result
  from edgar_private.membership_control c join edgar_private.membership_snapshots a on a.namespace=c.namespace and a.id=c.active_id
  left join edgar_private.membership_snapshots b on b.namespace=c.namespace and b.id=c.candidate_id where c.namespace=p_namespace;
  if result is null then raise exception 'membership_registry_missing'; end if;
  if octet_length(result::text)>524288 then raise exception 'membership_registry_size_limit'; end if;
  return result;
end $$;

create function public.edgar_begin_membership_check(p_namespace text,p_owner uuid)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare c edgar_private.membership_control;
begin
  if p_namespace is distinct from 'production' or p_owner is null then raise exception 'invalid_membership_claim' using errcode='22023'; end if;
  select * into c from edgar_private.membership_control where namespace=p_namespace for update;
  if not found then raise exception 'membership_registry_missing'; end if;
  if c.next_check_at>clock_timestamp() or (c.owner is not null and c.lease_until>clock_timestamp()) then return null; end if;
  update edgar_private.membership_control set owner=p_owner,generation=generation+1,lease_until=clock_timestamp()+interval '240 seconds'
    where namespace=p_namespace returning * into c;
  return jsonb_build_object('owner',c.owner,'generation',c.generation,'expiresAt',c.lease_until);
end $$;

create function public.edgar_stage_membership(p_namespace text,p_claim jsonb,p_snapshot jsonb,p_evidence jsonb)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare c edgar_private.membership_control; active jsonb; issuer_row jsonb; alias_value text; as_of date; checked timestamptz;
  fingerprint text; compressed bytea; issuer_count integer; security_count integer; retained_count integer;
  snapshot_id text; projected_size integer; old_snapshot jsonb;
begin
  if p_namespace is distinct from 'production' then raise exception 'invalid_membership_namespace' using errcode='22023'; end if;
  select * into c from edgar_private.membership_control where namespace=p_namespace for update;
  if not found or c.owner is distinct from (p_claim->>'owner')::uuid or c.generation is distinct from (p_claim->>'generation')::bigint
    or c.owner is null or c.lease_until<=clock_timestamp() then raise exception 'membership_claim_lost' using errcode='40001'; end if;
  if p_snapshot is null or jsonb_typeof(p_snapshot) is distinct from 'object' or octet_length(p_snapshot::text)>180000
    or p_snapshot->>'version' is distinct from 'sec-coverage-v1' or p_snapshot#>>'{reference,fund}' is distinct from 'IVV'
    or p_snapshot#>>'{reference,url}' is distinct from 'https://www.ishares.com/us/products/239726/ishares-core-s-p-500-etf/latest-holdings.csv'
    or p_snapshot#>>'{mapping,sourceUrl}' is distinct from 'https://www.sec.gov/files/company_tickers.json'
    or jsonb_typeof(p_snapshot->'issuers') is distinct from 'array' or jsonb_typeof(p_snapshot->'securities') is distinct from 'array'
    or (p_snapshot#>>'{reference,asOf}') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
    or (p_snapshot#>>'{sourceSnapshot,sha256}') !~ '^[a-f0-9]{64}$'
    or length(coalesce(p_snapshot#>>'{sourceSnapshot,path}','')) not between 1 and 512
    then raise exception 'invalid_membership_snapshot' using errcode='22023'; end if;
  as_of:=(p_snapshot#>>'{reference,asOf}')::date; checked:=(p_snapshot#>>'{reference,checkedAt}')::timestamptz;
  if as_of is null or checked is null or as_of>(clock_timestamp() at time zone 'UTC')::date
    or as_of<(clock_timestamp() at time zone 'UTC')::date-14 or checked>clock_timestamp()+interval '60 seconds'
    or checked<(as_of::timestamp at time zone 'UTC') or checked<clock_timestamp()-interval '15 minutes'
    or to_char(as_of,'YYYY-MM-DD')<>p_snapshot#>>'{reference,asOf}'
    then raise exception 'invalid_membership_source_dates' using errcode='22023'; end if;
  issuer_count:=jsonb_array_length(p_snapshot->'issuers'); security_count:=jsonb_array_length(p_snapshot->'securities');
  if issuer_count not between 475 and 525 or security_count not between 475 and 550
    or (p_snapshot->>'issuerCount')::integer is distinct from issuer_count or (p_snapshot->>'securityCount')::integer is distinct from security_count
    then raise exception 'invalid_membership_count' using errcode='22023'; end if;
  for issuer_row in select value from jsonb_array_elements(p_snapshot->'issuers') loop
    if jsonb_typeof(issuer_row) is distinct from 'object' or jsonb_typeof(issuer_row->'cik') is distinct from 'string' or jsonb_typeof(issuer_row->'name') is distinct from 'string' or coalesce(issuer_row->>'cik','') !~ '^[0-9]{10}$' or issuer_row->>'cik'='0000000000'
      or coalesce(issuer_row->>'ticker','') !~ '^[A-Z][A-Z0-9-]{0,9}$' or issuer_row->>'fund' is distinct from 'IVV'
      or length(trim(coalesce(issuer_row->>'name',''))) not between 1 and 300 or octet_length(issuer_row::text)>1200
      or coalesce(issuer_row->>'sector','') not in ('Communication','Consumer Discretionary','Consumer Staples','Energy','Financials','Health Care','Industrials','Information Technology','Materials','Real Estate','Utilities')
      or jsonb_typeof(issuer_row->'aliases') is distinct from 'array' then raise exception 'invalid_membership_issuer' using errcode='22023'; end if;
    if jsonb_array_length(issuer_row->'aliases') not between 1 and 10 or not (issuer_row->'aliases' ? (issuer_row->>'ticker'))
      then raise exception 'invalid_membership_aliases' using errcode='22023'; end if;
    for alias_value in select value from jsonb_array_elements_text(issuer_row->'aliases') loop
      if alias_value is null or alias_value !~ '^[A-Z][A-Z0-9-]{0,9}$' then raise exception 'invalid_membership_aliases' using errcode='22023'; end if;
    end loop;
  end loop;
  if (select count(distinct r->>'cik') from jsonb_array_elements(p_snapshot->'issuers') r)<>issuer_count
    or (select count(*) from jsonb_array_elements(p_snapshot->'issuers') r,jsonb_array_elements_text(r->'aliases') a)<>security_count
    or (select count(distinct a) from jsonb_array_elements(p_snapshot->'issuers') r,jsonb_array_elements_text(r->'aliases') a)<>security_count
    or (select count(distinct r->>'ticker') from jsonb_array_elements(p_snapshot->'securities') r)<>security_count
    or exists(select 1 from jsonb_array_elements(p_snapshot->'securities') s where not exists(
      select 1 from jsonb_array_elements(p_snapshot->'issuers') i where i->>'cik'=s->>'cik' and i->'aliases' ? (s->>'ticker')))
    then raise exception 'ambiguous_membership_mapping' using errcode='22023'; end if;
  fingerprint:=edgar_private.membership_fingerprint(p_snapshot->'issuers'); snapshot_id:=p_snapshot->>'id';
  if p_snapshot->>'membershipFingerprint' is distinct from fingerprint
    or snapshot_id is distinct from 'sec-coverage-v1:ivv:'||to_char(as_of,'YYYY-MM-DD')||':'||left(fingerprint,16)
    then raise exception 'membership_fingerprint_mismatch' using errcode='22023'; end if;
  select snapshot into active from edgar_private.membership_snapshots where namespace=p_namespace and id=c.active_id;
  if as_of<(active#>>'{reference,asOf}')::date then raise exception 'membership_date_moved_backward' using errcode='22023'; end if;
  if (select count(*) from jsonb_array_elements(p_snapshot->'issuers') n where not exists(select 1 from jsonb_array_elements(active->'issuers') o where n->>'cik'=o->>'cik'))>(active->>'issuerCount')::integer*0.05
    or (select count(*) from jsonb_array_elements(active->'issuers') o where not exists(select 1 from jsonb_array_elements(p_snapshot->'issuers') n where n->>'cik'=o->>'cik'))>(active->>'issuerCount')::integer*0.05
    then raise exception 'membership_turnover_review_required' using errcode='22023'; end if;
  -- Historical aliases are never reassigned automatically, including renamed securities.
  if exists(select 1 from jsonb_array_elements(p_snapshot->'issuers') n,jsonb_array_elements_text(n->'aliases') na
    join edgar_private.membership_aliases o on o.namespace=p_namespace and o.ticker=na where o.cik<>n->>'cik')
    then raise exception 'membership_ticker_reuse_review_required' using errcode='22023'; end if;
  if coalesce(p_snapshot#>>'{mapping,sourceSha256}','') !~ '^[a-f0-9]{64}$'
    or (p_snapshot#>>'{mapping,checkedAt}')::timestamptz is null
    or (p_snapshot#>>'{mapping,checkedAt}')::timestamptz>clock_timestamp()+interval '60 seconds'
    or (p_snapshot#>>'{mapping,checkedAt}')::timestamptz<clock_timestamp()-interval '15 minutes'
    then raise exception 'invalid_membership_mapping_evidence' using errcode='22023'; end if;
  if p_snapshot ? 'sourceExclusions' then
    if jsonb_typeof(p_snapshot->'sourceExclusions') is distinct from 'array' then raise exception 'invalid_membership_exclusions' using errcode='22023'; end if;
    if jsonb_array_length(p_snapshot->'sourceExclusions')>25 then raise exception 'invalid_membership_exclusions' using errcode='22023'; end if;
    for issuer_row in select value from jsonb_array_elements(p_snapshot->'sourceExclusions') loop
      if jsonb_typeof(issuer_row) is distinct from 'object' or coalesce(issuer_row->>'ticker','') !~ '^[A-Z][A-Z0-9-]{0,9}$'
        or length(trim(coalesce(issuer_row->>'name',''))) not between 1 and 300 or length(coalesce(issuer_row->>'exchange','')) not between 1 and 100
        or (issuer_row->>'exchange') !~* '^NO MARKET([[:space:]]|$)' or issuer_row->>'currency' is distinct from 'USD'
        or jsonb_typeof(issuer_row->'marketValueUsd') is distinct from 'number' or (issuer_row->>'marketValueUsd')::numeric not between 0 and 100000
        or issuer_row->'weightPercent' is distinct from '0'::jsonb
        or issuer_row->>'reason' is distinct from 'Unlisted residual holding, excluded from listed-security research coverage.'
        or exists(select 1 from jsonb_array_elements(p_snapshot->'securities') i where i->>'ticker'=issuer_row->>'ticker')
        then raise exception 'invalid_membership_exclusions' using errcode='22023'; end if;
    end loop;
    if (select count(distinct r->>'ticker') from jsonb_array_elements(p_snapshot->'sourceExclusions') r)<>jsonb_array_length(p_snapshot->'sourceExclusions')
      or (select coalesce(sum((r->>'marketValueUsd')::numeric),0) from jsonb_array_elements(p_snapshot->'sourceExclusions') r)>100000
      then raise exception 'invalid_membership_exclusions' using errcode='22023'; end if;
  end if;
  if p_evidence is null or jsonb_typeof(p_evidence) is distinct from 'object' or octet_length(p_evidence::text)>270000
    or coalesce(p_evidence->>'rawSha256','') !~ '^[a-f0-9]{64}$' or coalesce(p_evidence->>'gzipSha256','') !~ '^[a-f0-9]{64}$'
    or p_evidence->>'rawSha256' is distinct from p_snapshot#>>'{sourceSnapshot,sha256}'
    or coalesce(p_evidence->>'rawBytes','') !~ '^[0-9]{1,6}$' or (p_evidence->>'rawBytes')::integer not between 1 and 750000
    or length(coalesce(p_evidence->>'gzipBase64','')) not between 1 and 266668
    then raise exception 'invalid_membership_evidence' using errcode='22023'; end if;
  compressed:=decode(p_evidence->>'gzipBase64','base64');
  if octet_length(compressed) not between 1 and 200000 or encode(extensions.digest(compressed,'sha256'),'hex')<>p_evidence->>'gzipSha256'
    or substring(compressed from 1 for 3)<>decode('1f8b08','hex')
    then raise exception 'membership_evidence_hash_mismatch' using errcode='22023'; end if;
  if c.candidate_id is not null and c.candidate_id<>snapshot_id and exists(select 1 from edgar_private.membership_snapshots s where s.namespace=p_namespace and s.id=c.candidate_id and s.source_as_of>=(clock_timestamp() at time zone 'UTC')::date-14) then raise exception 'membership_candidate_pending' using errcode='40001'; end if;
  select snapshot into old_snapshot from edgar_private.membership_snapshots s where s.namespace=p_namespace and s.id=snapshot_id;
  if found and (old_snapshot->'issuers' is distinct from p_snapshot->'issuers' or old_snapshot->'securities' is distinct from p_snapshot->'securities'
      or old_snapshot->>'membershipFingerprint' is distinct from fingerprint)
    then raise exception 'membership_snapshot_immutable' using errcode='22023'; end if;
  select count(distinct cik) into retained_count from (
    select issuer->>'cik' cik from edgar_private.membership_retained where namespace=p_namespace
    union all select i->>'cik' from jsonb_array_elements(active->'issuers') i
    union all select i->>'cik' from jsonb_array_elements(p_snapshot->'issuers') i
    union all select '0000002098') all_admissions;
  if retained_count>2000 then raise exception 'membership_admission_limit' using errcode='22023'; end if;
  select octet_length(p_snapshot::text)+octet_length(active::text)+coalesce(sum(octet_length(issuer::text)+2),0)+10000
    into projected_size from edgar_private.membership_retained where namespace=p_namespace;
  if projected_size>524288 then raise exception 'membership_registry_size_limit' using errcode='22023'; end if;
  if c.lease_until<=clock_timestamp() then raise exception 'membership_claim_lost' using errcode='40001'; end if;
  insert into edgar_private.membership_snapshots(namespace,id,source_as_of,fingerprint,snapshot,evidence_kind,raw_sha256,raw_bytes,gzip_sha256,gzip_bytes)
  values(p_namespace,snapshot_id,as_of,fingerprint,p_snapshot,'gzip-csv',p_evidence->>'rawSha256',(p_evidence->>'rawBytes')::integer,p_evidence->>'gzipSha256',compressed)
    on conflict(namespace,id) do nothing;
  update edgar_private.membership_control set candidate_id=case when active_id=snapshot_id then null else snapshot_id end,
    last_checked_at=clock_timestamp(),last_error=null,error_count=0,
    preparation_cursor=case when candidate_id is distinct from snapshot_id then 0 else preparation_cursor end,
    next_check_at=clock_timestamp()+case when active_id=snapshot_id then interval '24 hours' else interval '5 minutes' end where namespace=p_namespace;
  return jsonb_build_object('staged',c.active_id<>snapshot_id,'unchanged',c.active_id=snapshot_id,'candidateId',case when c.active_id<>snapshot_id then snapshot_id else null end,'activeId',c.active_id);
end $$;

create function public.edgar_activate_membership(p_namespace text,p_claim jsonb,p_id text)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare c edgar_private.membership_control; candidate jsonb; previous jsonb; needed jsonb;
begin
  if p_namespace is distinct from 'production' then raise exception 'invalid_membership_namespace' using errcode='22023'; end if;
  select * into c from edgar_private.membership_control where namespace=p_namespace for update;
  if not found or c.owner is distinct from (p_claim->>'owner')::uuid or c.generation is distinct from (p_claim->>'generation')::bigint
    or c.owner is null or c.lease_until<=clock_timestamp() then raise exception 'membership_claim_lost' using errcode='40001'; end if;
  if p_id is null or c.candidate_id is distinct from p_id then raise exception 'membership_candidate_mismatch' using errcode='22023'; end if;
  select snapshot into candidate from edgar_private.membership_snapshots where namespace=p_namespace and id=p_id;
  select snapshot into previous from edgar_private.membership_snapshots where namespace=p_namespace and id=c.active_id;
  if (candidate#>>'{reference,asOf}')::date<(clock_timestamp() at time zone 'UTC')::date-14 then raise exception 'membership_candidate_stale' using errcode='22023'; end if;
  -- Lock all existing current heads while checking them and switching the registry.
  -- Missing heads cannot satisfy readiness, and new publications wait for this transaction.
  perform 1 from public.edgar_dataset_heads h where h.namespace=p_namespace and h.dataset in ('sec','financial')
    and (h.dataset='sec' and split_part(h.resource_key,':',2) in
      (select 'CIK'||(i->>'cik') from jsonb_array_elements(candidate->'issuers') i union select 'CIK0000002098' union select 'CIK0000034088')
      or h.dataset='financial' and h.resource_key ~ '^(financial-analysis-v1|research-compare-v1|research-portfolio-v1):'
      and split_part(h.resource_key,':',4) in (select 'CIK'||(i->>'cik') from jsonb_array_elements(candidate->'issuers') i union select 'CIK0000002098'))
    order by h.dataset,h.resource_key for share;
  with issuers as (
    select i->>'cik' cik from jsonb_array_elements(candidate->'issuers') i union select '0000002098'
  ), expected as (
    select cik,'sec' dataset,'sec-documents-v1:CIK'||cik||':'||resource resource_key,resource family,null::text basis
      from issuers cross join unnest(array['submissions','companyfacts']) resource
    union all
    select cik,'financial','financial-analysis-v1:analysis-v1.4:context-v3:CIK'||cik||':'||basis||':latest','analysis',basis
      from issuers cross join unnest(array['annual','quarter','ytd','ttm']) basis
    union all
    select cik,'financial','research-compare-v1:compare-v2:context-v3:CIK'||cik||':'||basis||':latest','compare',basis
      from issuers cross join unnest(array['annual','quarter','ttm']) basis
    union all
    select cik,'financial','research-portfolio-v1:analysis-v1.4:context-v3:CIK'||cik||':'||basis||':latest','portfolio',basis
      from issuers cross join unnest(array['annual','quarter','ytd','ttm']) basis
  ), invalid as (
    select distinct e.cik from expected e
    left join public.edgar_dataset_heads h on h.namespace=p_namespace and h.dataset=e.dataset and h.resource_key=e.resource_key
    left join public.edgar_dataset_versions v on v.id=h.current_version and v.namespace=h.namespace and v.dataset=h.dataset and v.resource_key=h.resource_key
    where v.id is null or h.expires_at is null or h.expires_at<=clock_timestamp() or h.revalidated_at is null or h.revalidated_at>clock_timestamp()+interval '60 seconds'
      or v.metadata->>'entityId' is distinct from e.cik
      or (v.object_path is not null and not exists(select 1 from storage.objects o where o.bucket_id='edgar-durable-private' and o.name=v.object_path))
      or (e.dataset='sec' and (coalesce(v.metadata->>'documentContentHash','') !~ '^[a-f0-9]{64}$'
        or v.metadata->>'resource' is distinct from e.family
        or not exists(select 1 from public.edgar_source_assets sa where sa.id=v.source_asset_id and sa.namespace=p_namespace and sa.dataset='sec'
          and sa.entity_id=e.cik and sa.content_hash=v.metadata->>'documentContentHash' and sa.source_url=case when e.family='submissions' then 'https://data.sec.gov/submissions/CIK'||e.cik||'.json'
            else 'https://data.sec.gov/api/xbrl/companyfacts/CIK'||e.cik||'.json' end
          and exists(select 1 from storage.objects o where o.bucket_id=sa.bucket and o.name=sa.object_path))))
      or (e.dataset='financial' and (v.metadata->>'basis' is distinct from e.basis
        or coalesce(v.metadata->>'financialInputHash','') !~ '^[a-f0-9]{64}$'
        or v.metadata->>'calculationVersion' is distinct from case when e.family='compare' then 'compare-v2:context-v3' else 'analysis-v1.4:context-v3' end
        or v.metadata->>'parserVersion' is distinct from case when e.family='analysis' then 'financial-analysis-v1' else 'research-serving-v1' end
        or (e.family='analysis' and v.metadata->>'metricProjectionVersion' is distinct from 'latest-all-v1')
        or jsonb_typeof(v.metadata->'inputDocuments') is distinct from 'array'
        or case when jsonb_typeof(v.metadata->'inputDocuments')='array' then
          jsonb_array_length(v.metadata->'inputDocuments') not between 2 and 4
          or (select count(distinct i->>'key') from jsonb_array_elements(v.metadata->'inputDocuments') i)<>jsonb_array_length(v.metadata->'inputDocuments')
          or not exists(select 1 from jsonb_array_elements(v.metadata->'inputDocuments') i where i->>'key'='sec-documents-v1:CIK'||e.cik||':submissions')
          or not exists(select 1 from jsonb_array_elements(v.metadata->'inputDocuments') i where i->>'key'='sec-documents-v1:CIK'||e.cik||':companyfacts')
          or exists(select 1 from jsonb_array_elements(v.metadata->'inputDocuments') i
            left join public.edgar_dataset_heads sh on sh.namespace=p_namespace and sh.dataset='sec' and sh.resource_key=i->>'key'
            left join public.edgar_dataset_versions sv on sv.id=sh.current_version and sv.namespace=sh.namespace and sv.dataset=sh.dataset and sv.resource_key=sh.resource_key
            where sv.id is null or sh.expires_at is null or sh.expires_at<=clock_timestamp()
              or i->>'contentHash' is distinct from sv.metadata->>'documentContentHash'
              or (i->>'versionId' is not null and i->>'versionId' is distinct from sv.id::text)
              or (i->>'generation' is not null and i->>'generation' is distinct from sv.publication_generation::text)
              or not (i->>'key' in ('sec-documents-v1:CIK'||e.cik||':submissions','sec-documents-v1:CIK'||e.cik||':companyfacts')
                or (e.cik='0002115436' and e.family in ('compare','portfolio') and i->>'key' in
                  ('sec-documents-v1:CIK0000034088:submissions','sec-documents-v1:CIK0000034088:companyfacts'))))
        else true end))
  ) select coalesce(jsonb_agg(cik order by cik),'[]'::jsonb) into needed from invalid;
  if jsonb_array_length(needed)>0 then
    -- Advance one slot per readiness call. Two calls per tick followed by preparing
    -- the first two issuers still traverse every pending issuer without starvation.
    select jsonb_agg(value order by (ordinal-1-c.preparation_cursor%jsonb_array_length(needed)+jsonb_array_length(needed))%jsonb_array_length(needed))
      into needed from jsonb_array_elements(needed) with ordinality n(value,ordinal);
    update edgar_private.membership_control set preparation_cursor=(c.preparation_cursor+1)%jsonb_array_length(needed) where namespace=p_namespace;
    return jsonb_build_object('activated',false,'neededCiks',needed,'activeId',c.active_id,'candidateId',p_id);
  end if;
  if c.lease_until<=clock_timestamp() then raise exception 'membership_claim_lost' using errcode='40001'; end if;
  insert into edgar_private.membership_aliases(namespace,ticker,cik,first_snapshot)
    select p_namespace,a,i->>'cik',p_id from jsonb_array_elements(candidate->'issuers') i,jsonb_array_elements_text(i->'aliases') a
    on conflict(namespace,ticker) do nothing;
  insert into edgar_private.membership_retained(namespace,cik,issuer,departed_snapshot)
    select p_namespace,i->>'cik',i,c.active_id from jsonb_array_elements(previous->'issuers') i
      where not exists(select 1 from jsonb_array_elements(candidate->'issuers') n where n->>'cik'=i->>'cik')
    on conflict(namespace,cik) do update set issuer=excluded.issuer,departed_snapshot=excluded.departed_snapshot,retained_at=clock_timestamp();
  insert into edgar_private.membership_activations(namespace,snapshot_id) values(p_namespace,p_id) on conflict do nothing;
  update edgar_private.membership_control set active_id=p_id,candidate_id=null,last_error=null,error_count=0,preparation_cursor=0,
    next_check_at=clock_timestamp()+interval '24 hours' where namespace=p_namespace;
  return jsonb_build_object('activated',true,'neededCiks','[]'::jsonb,'activeId',p_id,'candidateId',null);
end $$;

create function public.edgar_finish_membership_check(p_namespace text,p_claim jsonb,p_error text default null)
returns boolean language plpgsql security invoker set search_path='' as $$
declare changed integer;
begin
  if p_namespace is distinct from 'production' or (p_error is not null and p_error !~ '^[A-Za-z0-9_]{1,100}$')
    then raise exception 'invalid_membership_finish' using errcode='22023'; end if;
  update edgar_private.membership_control set owner=null,lease_until=null,last_error=p_error,
    error_count=case when p_error is null then 0 else least(error_count+1,3) end,
    next_check_at=clock_timestamp()+case when p_error is not null and error_count>=2 then interval '6 hours'
      when p_error is not null or candidate_id is not null then interval '5 minutes' else interval '24 hours' end
    where namespace=p_namespace and owner=(p_claim->>'owner')::uuid and generation=(p_claim->>'generation')::bigint and lease_until>clock_timestamp();
  get diagnostics changed=row_count; return changed=1;
end $$;

create function public.edgar_membership_admission(p_namespace text,p_ciks text[])
returns jsonb language plpgsql stable security invoker set search_path='' as $$
declare result jsonb;
begin
  if p_namespace is distinct from 'production' or p_ciks is null or coalesce(array_ndims(p_ciks),1)<>1 or cardinality(p_ciks)>100
    or exists(select 1 from unnest(p_ciks) c where c is null or c !~ '^[0-9]{10}$' or c='0000000000')
    then raise exception 'invalid_membership_admission' using errcode='22023'; end if;
  with admitted as (
    select i->>'cik' cik from edgar_private.membership_control c join edgar_private.membership_snapshots s
      on s.namespace=c.namespace and s.id in (c.active_id,c.candidate_id),jsonb_array_elements(s.snapshot->'issuers') i where c.namespace=p_namespace
    union select cik from edgar_private.membership_retained where namespace=p_namespace
    union select '0000002098'
  ) select jsonb_build_object('allowedCiks',coalesce(jsonb_agg(cik order by cik),'[]'::jsonb),
    'sourceOnlyCiks',case when '0000034088'=any(p_ciks) and not exists(select 1 from admitted where cik='0000034088')
      then '["0000034088"]'::jsonb else '[]'::jsonb end) into result from admitted where cik=any(p_ciks);
  return result;
end $$;

create function public.edgar_enqueue_current_coverage_jobs(p_namespace text,p_cycle text,p_shards integer[] default null)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare shards integer[]; shard integer; job_id uuid; job_key text; result jsonb:='[]'::jsonb;
  cycle_row edgar_private.coverage_cycles; c edgar_private.membership_control; companies jsonb; shard_companies jsonb; version text;
begin
  if p_namespace is distinct from 'production' or p_cycle is distinct from to_char(clock_timestamp() at time zone 'UTC','YYYY-MM-DD')
    then raise exception 'invalid_current_coverage_cycle' using errcode='22023'; end if;
  if p_shards is null then select array_agg(n) into shards from generate_series(0,31) n; else shards:=p_shards; end if;
  if coalesce(array_ndims(shards),1)<>1 or cardinality(shards) not between 1 and 32
    or exists(select 1 from unnest(shards) n where n is null or n not between 0 and 31)
    or cardinality(shards)<>(select count(distinct n) from unnest(shards) n)
    then raise exception 'invalid_coverage_shards' using errcode='22023'; end if;
  -- The registry row is the serialization fence shared with activation. Each UTC
  -- cycle captures exactly one immutable set even when membership changes midday.
  select * into c from edgar_private.membership_control where namespace=p_namespace for update;
  if not found then raise exception 'membership_registry_missing'; end if;
  select * into cycle_row from edgar_private.coverage_cycles where namespace=p_namespace and cycle=p_cycle::date;
  if not found then
    select jsonb_agg(jsonb_build_object('cik',cik,'ticker',ticker) order by cik) into companies from (
      select i->>'cik' cik,i->>'ticker' ticker from edgar_private.membership_snapshots s,jsonb_array_elements(s.snapshot->'issuers') i
        where s.namespace=p_namespace and s.id=c.active_id and i->>'cik'<>'0000002098'
      union all select '0000002098','ACU') cohort;
    version:=left(encode(extensions.digest(companies::text,'sha256'),'hex'),16);
    insert into edgar_private.coverage_cycles(namespace,cycle,membership_id,universe_version,companies)
      values(p_namespace,p_cycle::date,c.active_id,version,companies) returning * into cycle_row;
  end if;
  foreach shard in array shards loop
    select coalesce(jsonb_agg(i order by i->>'cik'),'[]'::jsonb) into shard_companies from jsonb_array_elements(cycle_row.companies) i
      where get_byte(extensions.digest(i->>'cik','sha256'),3)%32=shard;
    if jsonb_array_length(shard_companies)>64 then raise exception 'coverage_shard_size_limit' using errcode='22023'; end if;
    job_key:='sec-coverage-v1:'||p_cycle||':'||lpad(shard::text,2,'0')||':'||cycle_row.universe_version;
    job_id:=public.edgar_enqueue_job(p_namespace,'sec','sec-coverage-v1:shard:'||lpad(shard::text,2,'0'),job_key,
      jsonb_build_object('schema',2,'universeVersion',cycle_row.universe_version,'membershipId',cycle_row.membership_id,
        'universeCompanies',jsonb_array_length(cycle_row.companies),'companies',shard_companies,'shard',shard,'cycle',p_cycle,
        'cursor',0,'succeeded',0,'workCount',0,'retries','[]'::jsonb,'failures','[]'::jsonb),10);
    result:=result||jsonb_build_array(jsonb_build_object('shard',shard,'id',job_id,'jobKey',job_key,'universeVersion',cycle_row.universe_version));
  end loop;
  return result;
end $$;

revoke all on function edgar_private.membership_fingerprint(jsonb) from public,anon,authenticated;
grant execute on function edgar_private.membership_fingerprint(jsonb) to service_role;
revoke all on function public.edgar_coverage_registry(text) from public,anon,authenticated;
revoke all on function public.edgar_begin_membership_check(text,uuid) from public,anon,authenticated;
revoke all on function public.edgar_stage_membership(text,jsonb,jsonb,jsonb) from public,anon,authenticated;
revoke all on function public.edgar_activate_membership(text,jsonb,text) from public,anon,authenticated;
revoke all on function public.edgar_finish_membership_check(text,jsonb,text) from public,anon,authenticated;
revoke all on function public.edgar_membership_admission(text,text[]) from public,anon,authenticated;
revoke all on function public.edgar_enqueue_current_coverage_jobs(text,text,integer[]) from public,anon,authenticated;
grant execute on function public.edgar_coverage_registry(text) to service_role;
grant execute on function public.edgar_begin_membership_check(text,uuid) to service_role;
grant execute on function public.edgar_stage_membership(text,jsonb,jsonb,jsonb) to service_role;
grant execute on function public.edgar_activate_membership(text,jsonb,text) to service_role;
grant execute on function public.edgar_finish_membership_check(text,jsonb,text) to service_role;
grant execute on function public.edgar_membership_admission(text,text[]) to service_role;
grant execute on function public.edgar_enqueue_current_coverage_jobs(text,text,integer[]) to service_role;
